 */
public void removeParagraph(XWPFParagraph paragraph) {
    if (paragraphs.contains(paragraph)) {
        CTP ctP = paragraph.getCTP();
        XmlCursor c = ctP.newCursor();
        c.removeXml();
        c.dispose();
        paragraphs.remove(paragraph);
        bodyElements.remove(paragraph);
    }
}

