    Document document = DocumentHelper.readDocument(new InputSource(new StringReader(wObjectXml)));
    ctr.set(XmlObject.Factory.parse(document.getDocumentElement(), POIXMLTypeLoader.DEFAULT_XML_OPTIONS));
