        XWPFRun ele = runs.get(i);
        if (ele == source) {
            runs.set(i, xwpfRun);
        }
    }
    // iruns
    List<ISDTContents> iruns = getSdtElements();
    for (int i = 0; i < iruns.size(); i++) {
        ISDTContents ele = iruns.get(i);
        if (ele == source) {
            iruns.set(i, xwpfRun);
        }
    }
}

