protected void removeExtraSheetCell(XSSFSheet sheet, final int numOfPoints, final int orignSize, final int seriesSize) {
    if ((orignSize - seriesSize) > 0) {
        // clear extra sheet column
        for (int i = 0; i < (numOfPoints + 1); i++) {
            for (int j = orignSize; j > seriesSize; j--) {
                XSSFRow row = sheet.getRow(i);
                if (null == row) {
                    continue;
                }
                XSSFCell cell = row.getCell(j);
                if (null != cell) // PATH: Test should invoke the next XSSFRow.removeCell(...) [step in execution path]
                {
                    row.removeCell(cell);
                }
            }
        }
    }
}

