public String getText() {
    StringBuilder text = new StringBuilder();
    boolean addNewLine = false;
    for (int i = 0; i < sdtElements.size(); i++) {
        Object o = sdtElements.get(i);
        if (o instanceof XWPFParagraph) {
            appendParagraph(((XWPFParagraph) (o)), text);
            addNewLine = true;
        } else if (o instanceof XWPFTable) // PATH: Test should invoke the next XWPFStructuredDocumentTagContent.appendTable(...) [step in execution path]
        {
