    }
    for (String numId : numIdsMap.keySet()) {
        addPart = addPart.replaceAll(("<w:numId\\sw:val=\"" + numId) + "\"", ("<w:numId w:val=\"" + numIdsMap.get(numId)) + "\"");
    }
    return addPart.replaceAll(CROSS_REPLACE_STRING, "");
}

